struct Particle { public float X, Y, Vx, Vy; }
Particle[] pool = ArrayPool<Particle>.Shared.Rent(capacity);
Span<Particle> span = pool.AsSpan(0, active);
for (int i = 0; i < active; i++) {           // contiguous sweep
    span[i].X += span[i].Vx * dt;
    span[i].Y += span[i].Vy * dt;
}
// CollectionsMarshal.AsSpan(list) gives the same view over List<T>'s backing array.
